var RISK = { LOW: "low", MEDIUM: "medium", HIGH: "high" };
var normalizeMultilingualText = (text = "") => {
  if (!text || typeof text !== "string") return "";
  let cleaned = text.toLowerCase().trim();
  cleaned = cleaned.replace(/adanawa/g, "andanawa").replace(/andanne/g, "andanawa").replace(/andana/g, "andanawa").replace(/therenne\s*na\b/g, "therenne naha").replace(/therenne\s*nehe/g, "therenne naha").replace(/therum\s*ganna\s*ba\b/g, "therum ganna baha").replace(/nida\s*na\b/g, "nida ganne naha").replace(/nida\s*nehe/g, "nida ganne naha").replace(/ninda\s*yanne\s*na\b/g, "ninda yanne naha").replace(/baya\s*hithenawa/g, "baya").replace(/mahansi\b/g, "mahansiyi").replace(/['’]/g, "");
  cleaned = cleaned.replace(/[^\w\s\u0D80-\u0DFF]/g, " ");
  return cleaned.replace(/\s+/g, " ").trim();
};
